function dedup(text, ignoreCase, skipEmpty){
  var lines = String(text).split(/\r?\n/);
  if(skipEmpty){ lines = lines.filter(function(l){return l.trim()!=='';}); }
  var seen={}, out=[];
  for(var i=0;i<lines.length;i++){
    var key = ignoreCase ? lines[i].toLowerCase() : lines[i];
    if(!seen[key]){ seen[key]=1; out.push(lines[i]); }
  }
  return out.join('\n');
}
var EXPORTS={dedup:dedup};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RemoveDupForgePure = EXPORTS; }
